class Solution { vector<int> cookies,loads;int best=INT_MAX;void search(int index,int current){if(current>=best)return;if(index==(int)cookies.size()){best=current;return;}unordered_set<int> seen;for(int i=0;i<(int)loads.size();++i){if(!seen.insert(loads[i]).second)continue;int before=loads[i];loads[i]+=cookies[index];search(index+1,max(current,loads[i]));loads[i]=before;if(before==0)break;}}public:int distributeCookies(vector<int>& values,int k){cookies=values;sort(cookies.rbegin(),cookies.rend());loads.assign(k,0);search(0,0);return best;} };
